import{_ as p,a0 as o,w as d,s as r,I as a,x as s,a1 as t,A as l,ao as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"在 FreeDOS 中设置你的路径 | LCTT x X-CMD","titleTemplate":false,"description":"在 FreeDOS 中设置你的路径 | LCTT (202103) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 FreeDOS 中设置你的路径 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 FreeDOS 中设置你的路径 | LCTT (202103) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202103/20210224 Set your path in FreeDOS","title":"在 FreeDOS 中设置你的路径","tag":"202103","desc":""},"relativePath":"202103/20210224 Set your path in FreeDOS.md","filePath":"[post].md"}'),h={name:"202103/20210224 Set your path in FreeDOS.md"};function g(u,e,k,b,c,f){const i=o("Link");return d(),r("div",null,[e[26]||(e[26]=a("h1",{id:"在-freedos-中设置你的路径",tabindex:"-1"},[s("在 FreeDOS 中设置你的路径 "),a("a",{class:"header-anchor",href:"#在-freedos-中设置你的路径","aria-label":"Permalink to “在 FreeDOS 中设置你的路径”"},"​")],-1)),e[27]||(e[27]=a("blockquote",null,[a("p",null,"学习 FreeDOS 路径的知识，如何设置它，并且如何使用它。")],-1)),e[28]||(e[28]=a("p",null,[a("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/career_journey_road_gps_path_map_520.png?itok=PpL6jJgY",alt:"查看职业生涯地图",title:"Looking at a map for career journey"})],-1)),a("p",null,[e[1]||(e[1]=s("你在开源 ",-1)),t(i,{href:"https://www.freedos.org/"},{default:l(()=>[...e[0]||(e[0]=[s("FreeDOS",-1)])]),_:1}),e[2]||(e[2]=s(" 操作系统中所做的一切工作都是通过命令行完成的。命令行以一个 ",-1)),e[3]||(e[3]=a("em",null,"提示符",-1)),e[4]||(e[4]=s(" 开始，这是计算机说法的方式，“我准备好了。请给我一些事情来做。”你可以配置你的提示符的外观，但是默认情况下，它是：",-1))]),e[29]||(e[29]=n('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;</span></span></code></pre></div><p>从命令行中，你可以做两件事：运行一个内部命令或运行一个程序。外部命令是在你的 <code>FDOS</code> 目录中可找到的以单独文件形式存在的程序，以便运行程序包括运行外部命令。它也意味着你可以使用你的计算机运行应用程序软件来做一些东西。你也可以运行一个批处理文件，但是在这种情况下，你所做的全部工作就变成了运行批处理文件中所列出的一系列命令或程序。</p><h3 id="可执行应用程序文件" tabindex="-1">可执行应用程序文件 <a class="header-anchor" href="#可执行应用程序文件" aria-label="Permalink to “可执行应用程序文件”">​</a></h3><p>FreeDOS 可以运行三种类型的应用程序文件：</p><ol><li><strong>COM</strong> 是一个用机器语言写的，且小于 64 KB 的文件。</li><li><strong>EXE</strong> 也是一个用机器语言写的文件，但是它可以大于 64 KB 。此外，在 EXE 文件的开头部分有信息，用于告诉 DOS 系统该文件是什么类型的以及如何加载和运行。</li><li><strong>BAT</strong> 是一个使用文本编辑器以 ASCII 文本格式编写的 <em>批处理文件</em> ，其中包含以批处理模式执行的 FreeDOS 命令。这意味着每个命令都会按顺序执行到文件的结尾。</li></ol><p>如果你所输入的一个文件名称不能被 FreeDOS 识别为一个内部命令或一个程序，你将收到一个错误消息 “Bad command or filename” 。如果你看到这个错误，它意味着会是下面三种情况中的其中一种：</p><ol><li>由于某些原因，你所给予的名称是错误的。你可能拼错了文件名称，或者你可能正在使用错误的命令名称。检查名称和拼写，并再次尝试。</li><li>可能你正在尝试运行的程序并没有安装在计算机上。请确认它已经安装了。</li><li>文件确实存在，但是 FreeDOS 不知道在哪里可以找到它。</li></ol>',7)),a("p",null,[e[6]||(e[6]=s("在清单上的最后一项就是这篇文章的主题，它被称为路径。如果你已经习惯于使用 Linux 或 Unix ，你可能已经理解 ",-1)),t(i,{href:"https://opensource.com/article/17/6/set-path-linux"},{default:l(()=>[...e[5]||(e[5]=[s("PATH 变量",-1)])]),_:1}),e[7]||(e[7]=s(" 的概念。如果你是命令行的新手，那么路径是一个非常重要的足以让你舒适的东西。",-1))]),e[30]||(e[30]=n(`<h3 id="路径" tabindex="-1">路径 <a class="header-anchor" href="#路径" aria-label="Permalink to “路径”">​</a></h3><p>当你输入一个可执行应用程序文件的名称时，FreeDOS 必须能找到它。FreeDOS 会在一个具体指定的位置层次结构中查找文件：</p><ol><li>首先，它查找当前驱动器的活动目录（称为 <em>工作目录</em>）。如果你正在目录 <code>C:\\FDOS</code> 中，接着，你输入名称 <code>FOOBAR.EXE</code>，FreeDOS 将在 <code>C:\\FDOS</code> 中查找带有这个名称的文件。你甚至不需要输入完整的名称。如果你输入 <code>FOOBAR</code> ，FreeDOS 将查找任何带有这个名称的可执行文件，不管它是 <code>FOOBAR.EXE</code>，<code>FOOBAR.COM</code>，或 <code>FOOBAR.BAT</code>。只要 FreeDOS 能找到一个匹配该名称的文件，它就会运行该可执行文件。</li><li>如果 FreeDOS 不能找到你所输入名称的文件，它将查询被称为 <code>PATH</code> 的一些东西。每当 DOS 不能在当前活动命令中找到文件时，会指示 DOS 检查这个列表中目录。</li></ol><p>你可以随时使用 <code>path</code> 命令来查看你的计算机的路径。只需要在 FreeDOS 提示符中输入 <code>path</code> ，FreeDOS 就会返回你的路径设置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;path</span></span>
<span class="line"><span>PATH=C:\\FDOS\\BIN</span></span></code></pre></div><p>第一行是提示符和命令，第二行是计算机返回的东西。你可以看到 DOS 第一个查看的位置就是位于 <code>C</code> 驱动器上的 <code>FDOS\\BIN</code>。如果你想更改你的路径，你可以输入一个 <code>path</code> 命令以及你想使用的新路径：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;path=C:\\HOME\\BIN;C:\\FDOS\\BIN</span></span></code></pre></div><p>在这个示例中，我设置我的路径到我个人的 <code>BIN</code> 文件夹，我把它放在一个叫 <code>HOME</code> 的自定义目录中，然后再设置为 <code>FDOS/BIN</code>。现在，当你检查你的路径时：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;path</span></span>
<span class="line"><span>PATH=C:\\HOME\\BIN;C:\\FDOS\\BIN</span></span></code></pre></div><p>路径设置是按所列目录的顺序处理的。</p><p>你可能会注意到有一些字符是小写的，有一些字符是大写的。你使用哪一种都真的不重要。FreeDOS 是不区分大小写的，并且把所有的东西都作为大写字母对待。在内部，FreeDOS 使用的全是大写字母，这就是为什么你看到来自你命令的输出都是大写字母的原因。如果你以小写字母的形式输入命令和文件名称，在一个转换器将自动转换它们为大写字母后，它们将被执行。</p><p>输入一个新的路径来替换先前设置的路径。</p><h3 id="autoexec-bat-文件" tabindex="-1">autoexec.bat 文件 <a class="header-anchor" href="#autoexec-bat-文件" aria-label="Permalink to “autoexec.bat 文件”">​</a></h3><p>你可能遇到的下一个问题的是 FreeDOS 默认使用的第一个路径来自何处。这与其它一些重要的设置一起定义在你的 <code>C</code> 驱动器的根目录下的 <code>AUTOEXEC.BAT</code> 文件中。这是一个批处理文件，它在你启动 FreeDOS 时会自动执行（由此得名）。你可以使用 FreeDOS 程序 <code>EDIT</code> 来编辑这个文件。为查看或编辑这个文件的内容，输入下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;edit autoexec.bat</span></span></code></pre></div><p>这一行出现在顶部附近：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SET PATH=%dosdir%\\BIN</span></span></code></pre></div><p>这一行定义默认路径的值。</p><p>在你查看 <code>AUTOEXEC.BAT</code> 后，你可以通过依次按下面的按键来退出 EDIT 应用程序：</p><ol><li><code>Alt</code></li><li><code>f</code></li><li><code>x</code></li></ol><p>你也可以使用键盘快捷键 <code>Alt+X</code>。</p><h3 id="使用完整的路径" tabindex="-1">使用完整的路径 <a class="header-anchor" href="#使用完整的路径" aria-label="Permalink to “使用完整的路径”">​</a></h3><p>如果你在你的路径中忘记包含 <code>C:\\FDOS\\BIN</code> ，那么你将不能快速访问存储在这里的任何应用程序，因为 FreeDOS 不知道从哪里找到它们。例如，假设我设置我的路径到我个人应用程序集合：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;path=C:\\HOME\\BIN</span></span></code></pre></div><p>内置在命令行中应用程序仍然能正常工作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\cd HOME</span></span>
<span class="line"><span>C:\\HOME&gt;dir</span></span>
<span class="line"><span>ARTICLES</span></span>
<span class="line"><span>BIN</span></span>
<span class="line"><span>CHEATSHEETS</span></span>
<span class="line"><span>GAMES</span></span>
<span class="line"><span>DND</span></span></code></pre></div><p>不过，外部的命令将不能运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:HOME\\ARTICLES&gt;BZIP2 -c example.txt</span></span>
<span class="line"><span>Bad command or filename - &quot;BZIP2&quot;</span></span></code></pre></div><p>通过提供命令的一个 <em>完整路径</em> ，你可以总是执行一个在你的系统上且不在你的路径中的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:HOME\\ARTICLES&gt;C:\\FDOS\\BIN\\BZIP2 -c example.txt</span></span>
<span class="line"><span>C:HOME\\ARTICLES&gt;DIR</span></span>
<span class="line"><span>example.txb</span></span></code></pre></div><p>你可以使用同样的方法从外部介质或其它目录执行应用程序。</p><h3 id="freedos-路径" tabindex="-1">FreeDOS 路径 <a class="header-anchor" href="#freedos-路径" aria-label="Permalink to “FreeDOS 路径”">​</a></h3><p>通常情况下，你很可能希望在路径中保留 <code>C:\\PDOS\\BIN</code> ，因为它包含所有使用 FreeDOS 分发的默认应用程序。</p><p>除非你更改 <code>AUTOEXEC.BAT</code> 中的路径，否则将在重新启动后恢复默认路径。</p><p>现在，你知道如何在 FreeDOS 中管理你的路径，你能够以最适合你的方式了执行命令和维护你的工作环境。</p>`,35)),a("p",null,[a("em",null,[e[9]||(e[9]=s("致谢 ",-1)),t(i,{href:"https://www.ahuka.com/dos-lessons-for-self-study-purposes/dos-lesson-5-the-path/"},{default:l(()=>[...e[8]||(e[8]=[s("DOS 课程 5: 路径",-1)])]),_:1}),e[10]||(e[10]=s(" (在 CC BY-SA 4.0 协议下发布) 为本文提供的一些信息。",-1))])]),e[31]||(e[31]=a("hr",null,null,-1)),a("p",null,[e[12]||(e[12]=s("via: ",-1)),t(i,{href:"https://opensource.com/article/21/2/path-freedos"},{default:l(()=>[...e[11]||(e[11]=[s("https://opensource.com/article/21/2/path-freedos",-1)])]),_:1})]),a("p",null,[e[17]||(e[17]=s("作者：",-1)),t(i,{href:"https://opensource.com/users/ahuka"},{default:l(()=>[...e[13]||(e[13]=[s("Kevin O'Brien",-1)])]),_:1}),e[18]||(e[18]=s(" 选题：",-1)),t(i,{href:"https://github.com/lujun9972"},{default:l(()=>[...e[14]||(e[14]=[s("lujun9972",-1)])]),_:1}),e[19]||(e[19]=s(" 译者：",-1)),t(i,{href:"https://github.com/robsean"},{default:l(()=>[...e[15]||(e[15]=[s("robsean",-1)])]),_:1}),e[20]||(e[20]=s(" 校对：",-1)),t(i,{href:"https://github.com/wxy"},{default:l(()=>[...e[16]||(e[16]=[s("wxy",-1)])]),_:1})]),a("p",null,[e[23]||(e[23]=s("本文由 ",-1)),t(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[21]||(e[21]=[s("LCTT",-1)])]),_:1}),e[24]||(e[24]=s(" 原创编译，",-1)),t(i,{href:"https://linux.cn/"},{default:l(()=>[...e[22]||(e[22]=[s("Linux中国",-1)])]),_:1}),e[25]||(e[25]=s(" 荣誉推出",-1))])])}const m=p(h,[["render",g]]);export{S as __pageData,m as default};
